import {equity,duel} from './engine.js';
onmessage=({data:d})=>{try{let {s,p,id}=d,base=equity(s,p);let rows=[];if(s.length>1){let candidates=[['平均相手', (s.reduce((a,b)=>a+b)-s[0])/(s.length-1)],... [.25,.5,1,2].map(x=>[`${x} × 自分`,s[0]*x])];for(let [label,target] of candidates){let total=s.slice(1).reduce((a,b)=>a+b),v=Math.min(target,total*(s.length===2?1:.95)),ss=[s[0],v,...s.slice(2).map(x=>x*(total-v)/(total-s[1]))];if(s.length===2)ss=[s[0],total];rows.push({label,actual:ss[1],...duel(ss,p)});}}let delta=s[0]*.05,total=s.slice(1).reduce((a,b)=>a+b),marginal=null;if(total>delta){let up=[s[0]+delta,...s.slice(1).map(x=>x*(total-delta)/total)],dn=[s[0]-delta,...s.slice(1).map(x=>x*(total+delta)/total)];marginal=(equity(up,p).value-equity(dn,p).value)/(2*delta);}postMessage({id,base,rows,marginal});}catch(e){postMessage({id:d.id,error:e.message});}};
